SQL:
WITH t AS (
SELECT l.user_id AS user_id FROM graph_tag_idcard_base g JOIN rzx_wz_wldt_logs l ON g.gmsfhm = l.auth_account OR g.lxdh = l.auth_account WHERE g.xm = '张晓欧'
), 
t2 AS (
SELECT l.auth_account FROM rzx_wz_wldt_logs l JOIN t ON l.to_user_id = t.user_id
)
SELECT g.xm, g.gmsfhm FROM graph_tag_idcard_base g JOIN t2 ON g.gmsfhm = t2.auth_account OR g.lxdh = t2.auth_account;

WITH t AS (
SELECT l.user_id AS user_id FROM graph_tag_idcard_base g JOIN rzx_wz_wldt_logs l ON g.gmsfhm = l.auth_account OR g.lxdh = l.auth_account WHERE g.xm = '张晓欧'
), 
t2 AS (
SELECT l.auth_account FROM rzx_wz_wldt_logs l JOIN t ON l.to_user_id = t.user_id WHERE l.capture_time >= strftime('%s', 'now', '-1 day') * 1000 AND l.capture_time < strftime('%s', 'now') * 1000
)
SELECT g.xm, g.gmsfhm FROM graph_tag_idcard_base g JOIN t2 ON g.gmsfhm = t2.auth_account OR g.lxdh = t2.auth_account;
